@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogHome>
@{
    Layout = "_Layout.cshtml";
}

<header class="mx-auto max-w-3xl px-6 pt-16">
    <h1 class="text-4xl font-bold">@Model.Title</h1>
</header>

<main class="mx-auto max-w-3xl px-6 pb-16">
    <div class="mt-8">
        @await Html.GetBlockGridHtmlAsync(Model, "blocks")
    </div>

    <section class="mt-16 space-y-10">
        @foreach (var post in Model.Children<BlogPost>().OrderByDescending(p => p.PublishDate))
        {
            <article>
                <p class="text-sm text-gray-500">@post.PublishDate.ToString("d MMMM yyyy")</p>
                <h2 class="mt-1 text-2xl font-semibold">
                    <a href="@post.Url()" class="hover:underline">@post.Title</a>
                </h2>
                <p class="mt-2 text-gray-700">@post.Summary</p>
            </article>
        }
    </section>
</main>

