<article class="mx-auto max-w-3xl px-6 py-16">
    <p class="text-sm text-gray-500">
        <a href="@Model.Parent?.Url()" class="hover:underline">&larr; Back to the journal</a>
    </p>

    <header class="mt-6">
        <h1 class="text-4xl font-bold">@Model.Title</h1>
